python
def pressParenthesesPositiveInkInvoice(readings):
    a=readings
    out=[]
    n=max(0,len(a)-1)
    dp=[[0]*n for _ in range(n)]
    for length in range(2,n+1):
        for left in range(n-length+1):
            right=left+length-1
            dp[left][right]=min(dp[left][m]+dp[m+1][right]+a[left]*a[m+1]*a[right+1] for m in range(left,right))
    out=[dp[0][r] for r in range(n)]
    return sum(x for x in out if x>0)


java
class Solution {
  public int pressParenthesesPositiveInkInvoice(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int n=Math.max(0,a.length-1);int[][]dp=new int[n][n];for(int len=2;len<=n;len++)for(int l=0;l+len<=n;l++){int r=l+len-1;dp[l][r]=Integer.MAX_VALUE;for(int m=l;m<r;m++)dp[l][r]=Math.min(dp[l][r],dp[l][m]+dp[m+1][r]+a[l]*a[m+1]*a[r+1]);}for(int r=0;r<n;r++)out.add(dp[0][r]);}
    int answer=0;for(int x:out)if(x>0)answer+=x;return answer;
  }
}
